<?php $opts = fn($q) => implode("\n", json_dec($q['options'])); $ans = fn($q) => implode(', ', array_map(fn($x) => $x + 1, json_dec($q['answer']))); ?>
<p class="small"><a href="/admin/courses/<?= (int) $c['id'] ?>#content"><?= icon('back', 14) ?> Back to <?= e($c['title']) ?></a></p>
<form class="panel" method="post" action="/admin/courses/<?= (int) $c['id'] ?>/lesson/<?= (int) $l['id'] ?>" enctype="multipart/form-data" style="max-width:900px"><?= csrf_field() ?><div class="panel-b form">
  <div class="row3"><?= a_in('Lesson title', 'title', $l['title'], ['required' => true]) ?><?= a_sel('Type', 'kind', ['video' => 'Video', 'text' => 'Reading', 'file' => 'Download', 'quiz' => 'Quiz'], $l['kind']) ?><?= a_sel('Section', 'module_id', array_column($mods, 'title', 'id'), $l['module_id']) ?></div>
  <div class="row3"><?= a_in('Duration (minutes)', 'duration_min', $l['duration_min'], ['type' => 'number', 'min' => 0]) ?><?= a_check('Free preview (visible without enrolling)', 'is_preview', $l['is_preview']) ?><?php if ($l['kind'] === 'quiz'): ?><?= a_in('Pass mark (%)', 'pass_mark', $l['pass_mark'], ['type' => 'number', 'min' => 1]) ?><?php endif; ?></div>
  <?php if ($l['kind'] === 'video'): ?><?= a_in('Video link (YouTube, Vimeo or direct .mp4)', 'video_url', $l['video_url'], ['hint' => 'Or upload a video file below. Unlisted YouTube videos work well.']) ?><?php else: ?><input type="hidden" name="video_url" value="<?= e($l['video_url']) ?>"><?php endif; ?>
  <?= a_in($l['kind'] === 'quiz' ? 'Instructions shown above the quiz' : 'Lesson text', 'body', $l['body'], ['type' => 'textarea', 'rows' => $l['kind'] === 'quiz' ? 3 : 12, 'hint' => 'Supports **bold**, _italic_, lists, ## headings, > quotes and [links](https://…).']) ?>
  <?php if (in_array($l['kind'], ['video', 'file'], true)): ?><div class="field"><label for="f-file"><?= $l['kind'] === 'video' ? 'Upload a video file (MP4/WebM)' : 'Downloadable file' ?></label><input id="f-file" type="file" name="file"><?php if ($l['file_path']): ?><span class="hint">Current file: <strong><?= e($l['file_name']) ?></strong> <label class="check" style="display:inline-flex"><input type="checkbox" name="remove_file" value="1"> remove</label></span><?php endif; ?></div><?php endif; ?>
  <?php if ($l['kind'] === 'quiz'): ?>
  <h3>Questions</h3><p class="muted small mb0">Write one option per line. Enter the number(s) of the correct option(s), e.g. <code>2</code> or <code>1, 3</code> for multiple correct answers.</p>
  <div id="qs"><?php foreach ($questions as $q): ?><div class="panel" style="margin:0 0 12px"><div class="panel-b form"><?= a_in('Question', 'q_prompt[]', $q['prompt']) ?><div class="row2"><div class="field"><label>Options (one per line)</label><textarea name="q_options[]" rows="4"><?= e($opts($q)) ?></textarea></div><div class="field"><label>Correct option number(s)</label><input name="q_answer[]" value="<?= e($ans($q)) ?>"><label style="margin-top:8px">Explanation (shown after answering)</label><input name="q_expl[]" value="<?= e($q['explanation']) ?>"></div></div><button type="button" class="link danger" onclick="this.closest('.panel').remove()">Remove question</button></div></div><?php endforeach; ?></div>
  <button type="button" class="btn btn-ghost btn-sm" id="addQ"><?= icon('plus', 14) ?> Add question</button>
  <template id="qt"><div class="panel" style="margin:0 0 12px"><div class="panel-b form"><div class="field"><label>Question</label><input name="q_prompt[]"></div><div class="row2"><div class="field"><label>Options (one per line)</label><textarea name="q_options[]" rows="4"></textarea></div><div class="field"><label>Correct option number(s)</label><input name="q_answer[]"><label style="margin-top:8px">Explanation</label><input name="q_expl[]"></div></div><button type="button" class="link danger" onclick="this.closest('.panel').remove()">Remove question</button></div></div></template>
  <script>document.getElementById('addQ').onclick=function(){document.getElementById('qs').appendChild(document.getElementById('qt').content.cloneNode(true))};</script><?php endif; ?>
  <div style="display:flex;gap:10px;flex-wrap:wrap"><button class="btn btn-primary">Save lesson</button></div>
</div></form>
